    # Find the smallest period that assigns each observed stripe phase one color.
    period = None
    for p in range(1, max(h, w) + 1):
        phase_colors = {}
        valid = True
        for q, color in samples:
            phase = q % p
            if phase in phase_colors and phase_colors[phase] != color:
                valid = False
                break
            phase_colors[phase] = color
        if valid:
            period = p
            break
    phase_colors = {}
    for q, color in samples:
        phase_colors[q % period] = color
    fallback = Counter(color for _, color in samples).most_common(1)[0][0]
    return [[phase_colors.get(fn(r, c) % period, fallback) for c in range(w)] for r in range(h)]

